# -*- coding: utf-8 -*-
# HFSS (AEDT) IronPython script -- unit-cell EIGENMODE of the Phase 30 cell "S1_supercell_leaky" (generated by lwmom). NOT run in AEDT by the author. MODEL_ONLY predictions: see README / predictions.json.
# Run inside AEDT: Tools > Run Script...   NOT run in AEDT by the author: check the boundary dialogs (see README).
#   cell 3.2 x 3.2 mm (x N cells for a supercell), Rogers RO3010 (eps_r 10.2, tan d 0.0022) 1.575 mm on a PEC ground, air up to 30.0 mm
#   with a PEC lid, patch: circle D = 0.0 mm super-ellipse n=4 3.050 x 3.050 mm, slot 1.89 x 0.58 mm along x
#   Master/slave pairs in x and y with Bloch phase: phase_x, phase_y (design variables).
import ScriptEnv
ScriptEnv.Initialize("Ansoft.ElectronicsDesktop")
oDesktop.RestoreWindow()
oProject = oDesktop.NewProject()
oProject.InsertDesign("HFSS", "S1_supercell_leaky", "Eigenmode", "")
oDesign = oProject.SetActiveDesign("S1_supercell_leaky")
oEditor = oDesign.SetActiveEditor("3D Modeler")
oEditor.SetModelUnits(["NAME:Units Parameter", "Units:=", "mm", "Rescale:=", False])

P = 3.2; H = 0.635; LID = 30.0; D = 0.0
PX_CELLS = 7
MAJOR = 3.0500000000000003; MINOR = 3.0500000000000003; EXPO = 4.0
SLOT_L = 1.891; SLOT_W = 0.58
PHASE_X = "6.744deg"     # along x: 6.744 deg, 0 deg; along the diagonal: 0 deg, 0 deg
PHASE_Y = "0deg"

oProject.GetDefinitionManager().AddMaterial(["NAME:HMSA_substrate", "CoordinateSystemType:=", "Cartesian",
    "BulkOrSurfaceType:=", 1, ["NAME:PhysicsTypes", "set:=", ["Electromagnetic"]],
    "permittivity:=", "10.2", "dielectric_loss_tangent:=", "0.0022"])

def attrs(name, material, solve_inside, color="(255 128 0)", transp=0):
    return ["NAME:Attributes", "Name:=", name, "Flags:=", "", "Color:=", color, "Transparency:=", transp,
            "PartCoordinateSystem:=", "Global", "UDMId:=", "", "MaterialValue:=", '"' + material + '"',
            "SurfaceMaterialValue:=", '""', "SolveInside:=", solve_inside, "IsMaterialEditable:=", True,
            "UseMaterialAppearance:=", False, "IsLightweight:=", False]

def mm(v):
    return repr(float(v)) + "mm"

# substrate and air column (centred on the origin)
oEditor.CreateBox(["NAME:BoxParameters", "XPosition:=", mm(-P * PX_CELLS / 2), "YPosition:=", mm(-P / 2), "ZPosition:=", "0mm",
    "XSize:=", mm(P * PX_CELLS), "YSize:=", mm(P), "ZSize:=", mm(H)], attrs("Substrate", "HMSA_substrate", True, "(0 128 0)", 0.6))
oEditor.CreateBox(["NAME:BoxParameters", "XPosition:=", mm(-P * PX_CELLS / 2), "YPosition:=", mm(-P / 2), "ZPosition:=", mm(H),
    "XSize:=", mm(P * PX_CELLS), "YSize:=", mm(P), "ZSize:=", mm(LID)], attrs("Air", "air", True, "(143 175 143)", 0.9))

# patch: circle minus a rotated rectangular slot, a sheet at z = H

def squircle_pts(a, b, n_exp, rot_deg, nv=72):
    pts = []
    for k in range(nv):
        t = 2.0 * math.pi * k / nv
        c, s = math.cos(t), math.sin(t)
        u = 0.5 * a * math.copysign(abs(c) ** (2.0 / n_exp), c)
        v = 0.5 * b * math.copysign(abs(s) ** (2.0 / n_exp), s)
        pts.append((u, v))
    r = math.radians(rot_deg); cr, sr = math.cos(r), math.sin(r)
    return [(u * cr - v * sr, u * sr + v * cr) for (u, v) in pts]

def poly(name, pts, z, cx=0.0, cy=0.0):
    oEditor.CreatePolyline(["NAME:PolylineParameters", "IsPolylineCovered:=", True, "IsPolylineClosed:=", True,
        ["NAME:PolylinePoints"] + [["NAME:PLPoint", "X:=", mm(cx + x), "Y:=", mm(cy + y), "Z:=", mm(z)] for (x, y) in pts + [pts[0]]],
        ["NAME:PolylineSegments"] + [["NAME:PLSegment", "SegmentType:=", "Line", "StartIndex:=", k, "NoOfPoints:=", 2] for k in range(len(pts))],
        ["NAME:PolylineXSection", "XSectionType:=", "None", "XSectionOrient:=", "Auto", "XSectionWidth:=", "0mm",
         "XSectionTopWidth:=", "0mm", "XSectionHeight:=", "0mm", "XSectionNumSegments:=", "0", "XSectionBendType:=", "Corner"]],
        attrs(name, "vacuum", True))

def make_patch(name, a, b, n_exp, sl, sw, rot_deg, cx=0.0, cy=0.0):
    poly(name, squircle_pts(a, b, n_exp, rot_deg), H, cx, cy)
    if sl > 0.0 and sw > 0.0:
        r = math.radians(rot_deg); cr, sr = math.cos(r), math.sin(r)
        rc = [(-sl / 2, -sw / 2), (sl / 2, -sw / 2), (sl / 2, sw / 2), (-sl / 2, sw / 2)]
        poly(name + "_slot", [(u * cr - v * sr, u * sr + v * cr) for (u, v) in rc], H, cx, cy)
        oEditor.Subtract(["NAME:Selections", "Blank Parts:=", name, "Tool Parts:=", name + "_slot"],
                         ["NAME:SubtractParameters", "KeepOriginals:=", False])

PATCHES = []
make_patch("Patch0", MAJOR, MINOR, EXPO, SLOT_L, SLOT_W, 0.0000, -9.6000, 0.0000); PATCHES.append("Patch0")
make_patch("Patch1", MAJOR, MINOR, EXPO, SLOT_L, SLOT_W, 25.7143, -6.4000, 0.0000); PATCHES.append("Patch1")
make_patch("Patch2", MAJOR, MINOR, EXPO, SLOT_L, SLOT_W, 51.4286, -3.2000, 0.0000); PATCHES.append("Patch2")
make_patch("Patch3", MAJOR, MINOR, EXPO, SLOT_L, SLOT_W, 77.1429, 0.0000, 0.0000); PATCHES.append("Patch3")
make_patch("Patch4", MAJOR, MINOR, EXPO, SLOT_L, SLOT_W, 102.8571, 3.2000, 0.0000); PATCHES.append("Patch4")
make_patch("Patch5", MAJOR, MINOR, EXPO, SLOT_L, SLOT_W, 128.5714, 6.4000, 0.0000); PATCHES.append("Patch5")
make_patch("Patch6", MAJOR, MINOR, EXPO, SLOT_L, SLOT_W, 154.2857, 9.6000, 0.0000); PATCHES.append("Patch6")

oEditor.CreateRectangle(["NAME:RectangleParameters", "IsCovered:=", True, "XStart:=", mm(-P * PX_CELLS / 2), "YStart:=", mm(-P / 2),
    "ZStart:=", "0mm", "Width:=", mm(P * PX_CELLS), "Height:=", mm(P), "WhichAxis:=", "Z"], attrs("Ground", "vacuum", True, "(128 128 128)"))


oBnd = oDesign.GetModule("BoundarySetup")
for nm in PATCHES + ["Ground"] + ([] if True else ["Lid"]):
    oBnd.AssignPerfectE(["NAME:PerfE_" + nm, "Objects:=", [nm], "InfGroundPlane:=", False])

def faces_at(x, y):
    ids = []
    for body, z in (("Substrate", H / 2.0), ("Air", H + LID / 2.0)):
        ids.append(int(oEditor.GetFaceByPosition(["NAME:FaceParameters", "BodyName:=", body,
                                                  "XPosition:=", mm(x), "YPosition:=", mm(y), "ZPosition:=", mm(z)])))
    return ids

# Lattice pairs. If a property name differs in your AEDT version, assign the same pairs in the GUI
# (HFSS > Boundaries > Assign > Primary / Secondary, phase delay = PHASE_X / PHASE_Y) -- see README.
try:
    # (tag, master-face centre, slave-face centre, phase, U vector start/end along the face)
    pairs = (("X", (-P * PX_CELLS / 2, 0.0), (P * PX_CELLS / 2, 0.0), PHASE_X, ((-P * PX_CELLS / 2, -P / 2), (-P * PX_CELLS / 2, P / 2)), ((P * PX_CELLS / 2, -P / 2), (P * PX_CELLS / 2, P / 2))),
             ("Y", (0.0, -P / 2), (0.0, P / 2), PHASE_Y, ((-P * PX_CELLS / 2, -P / 2), (P * PX_CELLS / 2, -P / 2)), ((-P * PX_CELLS / 2, P / 2), (P * PX_CELLS / 2, P / 2))))
    for tag, mc, sc, phase, mu, su in pairs:
        oBnd.AssignMaster(["NAME:Master" + tag, "Faces:=", faces_at(mc[0], mc[1]),
            "CoordSysVector:=", ["NAME:Vectors", "Origin:=", [mm(mu[0][0]), mm(mu[0][1]), "0mm"],
                                 "UPos:=", [mm(mu[1][0]), mm(mu[1][1]), "0mm"]],
            "ReverseV:=", False])
        oBnd.AssignSlave(["NAME:Slave" + tag, "Faces:=", faces_at(sc[0], sc[1]),
            "CoordSysVector:=", ["NAME:Vectors", "Origin:=", [mm(su[0][0]), mm(su[0][1]), "0mm"],
                                 "UPos:=", [mm(su[1][0]), mm(su[1][1]), "0mm"]],
            "ReverseU:=", False, "Master:=", "Master" + tag, "UseScanAngle:=", False, "PhaseDelay:=", phase])
except Exception as exc:
    oDesktop.AddMessage(oProject.GetName(), "S1_supercell_leaky", 1, "Master/slave assignment failed (" + str(exc) + "): assign the X and Y pairs by hand, see README.")

oBnd.AssignRadiation(["NAME:RadTop", "Faces:=", [int(oEditor.GetFaceByPosition(["NAME:FaceParameters", "BodyName:=", "Air", "XPosition:=", "0mm", "YPosition:=", "0mm", "ZPosition:=", mm(H + LID)]))], "IsFssReference:=", False, "IsForPML:=", False])
oAna = oDesign.GetModule("AnalysisSetup")
oAna.InsertSetup("HfssEigen", ["NAME:Setup1", "MinimumFrequency:=", "8GHz", "NumModes:=", 6, "MaxDeltaFreq:=", 0.1,
    "ConvergeOnRealFreq:=", True, "MaximumPasses:=", 15, "MinimumPasses:=", 2, "MinimumConvergedPasses:=", 2,
    "PercentRefinement:=", 30, "IsEnabled:=", True, "BasisOrder:=", 1])
oEditor.FitAll()
oProject.SaveAs(oDesktop.GetProjectDirectory() + "/S1_supercell_leaky.aedt", True)
oDesktop.AddMessage(oProject.GetName(), "S1_supercell_leaky", 0, "Built. Set the phases, then Analyze: the bound mode is the lowest eigenmode whose field decays away from the patch plane.")
